INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_SAMARITAN','Samaritan Era (Gerizim cult to present)',-400,2025)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_ANDERSON_GILES_KEEPERS','secondary scholarship','Robert T. Anderson & Terry Giles, The Keepers: An Introduction to the History and Culture of the Samaritans (Hendrickson, 2002)','Survey of Samaritan history, religion, the Mt Gerizim cult, the priesthood, Marqah and Baba Rabba, and the Taheb expectation.'),
 ('SRC_PUMMER_SAMARITANS','secondary scholarship','Reinhard Pummer, The Samaritans: A Profile (Eerdmans, 2016)','Standard scholarly profile of Samaritan religion, scripture, theology (Moses, the Glory, angels), priestly genealogy, and messianism.'),
 ('SRC_MEMAR_MARQAH','primary text','Memar Marqah (Tibat Marqe), 4th-c. Samaritan Aramaic theological treatise attributed to Marqah, ed./trans. J. Macdonald (BZAW 84, 1963)','Foundational Samaritan theological work on Moses as supreme prophet, the divine Glory, and creation.')
INSERT INTO _e VALUES
 ('ENT_SAM_PANTHEON','Samaritan Pantheon / Sacred Cohort','Collective','Collective','Samaritan','Samaritan Israelite religion centered on Mount Gerizim','B','Organizing hub for the Samaritan tradition (deity, prophets, priests, eschatology, sacred realm). Modeling device, not an attested ''pantheon'' — Samaritanism is strictly monotheistic.'),
 ('ENT_SAM_SHEMA','Shema (the One God of the Samaritans)','Deity','Deity','Samaritan','The one God of Israel as worshipped on Mount Gerizim','B','Samaritans confess strict monotheism of the God of Israel; commonly invoke ''Shema'' (the Name / the One) and the tetragrammaton-equivalent of Israelite faith. Same God as Israelite Yahweh; distinct cult on Gerizim. Attested in Samaritan liturgy and Pummer.'),
 ('ENT_SAM_MOSES','Moses (Samaritan: Moshe, the supreme prophet)','Prophet / Lawgiver','Prophet / Lawgiver','Samaritan','Lawgiver and unique mediator of the Torah','B','In Samaritan theology Moses is the unsurpassable prophet, sole revealer of the complete Torah, sometimes given pre-cosmic dignity in Memar Marqah; no later prophet is canonical. Homonym/reception of the Israelite Moses (ENT_ISR_MOSES).'),
 ('ENT_SAM_TAHEB','Taheb (the Samaritan Restorer)','Eschatological figure','Eschatological figure','Samaritan','Eschatological restorer and prophet-like-Moses','B','The Taheb (''the one who returns/restores'') is the Samaritan messianic figure, a prophet like Moses (Deut 18:18) who will restore true worship on Gerizim and the hidden cult vessels; attested in Samaritan sources and discussed by Pummer and Anderson-Giles. Functional analogue of the Jewish Messiah.'),
 ('ENT_SAM_MARQAH','Marqah (Marqe)','Theologian','Theologian','Samaritan','Foundational Samaritan theologian and poet','B','4th-c. CE Samaritan theologian, traditional author of the Memar Marqah (Tibat Marqe) and liturgical poems; the great systematizer of Samaritan theology of Moses and the Glory. Historical figure.'),
 ('ENT_SAM_BABA_RABBA','Baba Rabba','Reformer / Leader','Reformer / Leader','Samaritan','Religious-political reformer of the Samaritan community','B','4th-c. CE Samaritan reformer who reorganized the community, established sages/hukama and synagogue worship, traditionally associated with a Samaritan revival; historical figure attested in the Samaritan chronicles and Anderson-Giles.'),
 ('ENT_SAM_HIGH_PRIEST','Samaritan High Priest (the High-Priestly Line)','Office / Lineage','Office / Lineage','Samaritan','Hereditary high priesthood of the Samaritans','B','The hereditary Samaritan high priesthood, claimed from Aaron/Levi via Phinehas (and after that line''s end, from the Levitical line of Uzziel); the living head of the community on Gerizim. Continuous office, well attested.'),
 ('ENT_SAM_PHINEHAS','Phinehas (Samaritan priestly ancestor)','Priest / Ancestor','Priest / Ancestor','Samaritan','Eponymous ancestor of the high-priestly line','C','Phinehas son of Eleazar son of Aaron is venerated as the zealous priest and ancestor of the Samaritan high-priestly line (the ''Pinhasite'' priesthood). Pentateuchal figure read through Samaritan priestly genealogy.'),
 ('ENT_SAM_GERIZIM','Mount Gerizim (Har Brakha / Argarizim)','Sacred place','Sacred place','Samaritan','The chosen sacred mountain and cult-center','B','Mount Gerizim is the Samaritan ''chosen place'' (the tenth commandment in the Samaritan Decalogue), site of the temple/altar, the Passover sacrifice, and the eschatological restoration; the central sacred realm of the religion. Archaeologically and textually attested.'),
 ('ENT_SAM_GLORY','The Glory (Kavod / the divine Light)','Divine attribute / Manifestation','Divine attribute / Manifestation','Samaritan','The manifest divine Glory/Light revealed to Moses','C','Samaritan theology (esp. Memar Marqah) develops the divine Glory/Light (the Kavod) as God''s manifestation at Sinai and upon Moses'' face; a mediating presence akin to but distinct from the Jewish Shekhinah/Kavod. Attested in Marqah.'),
 ('ENT_SAM_ANGEL','The Angel of the LORD (Samaritan Malak)','Angelic being','Angelic being','Samaritan','Created angelic mediator of the divine presence','C','Samaritan theology recognizes the Angel/Malak as a created mediator of God''s word and presence (e.g., the Angel at the burning bush and Sinai), within a strictly monotheistic framework; discussed in Pummer and Memar Marqah.'),
 ('ENT_SAM_TORAH','Samaritan Torah (Samaritan Pentateuch)','Scripture','Scripture','Samaritan','The sole Samaritan scriptural canon','B','The Samaritan Pentateuch (Samaritan Hebrew Torah) is the entire Samaritan canon, with distinctive readings (notably the Gerizim commandment); the Abisha Scroll is its most venerated copy. Well attested textual tradition.'),
 ('ENT_SAM_PASSOVER','Samaritan Passover Sacrifice (Pesach on Gerizim)','Ritual','Ritual','Samaritan','Annual paschal lamb sacrifice on Mount Gerizim','B','The living Samaritan Passover sacrifice on Mount Gerizim is the most distinctive surviving Israelite blood-sacrifice; publicly attested annual ritual. Modeled only at the level of public observance, not ritual interiors.'),
 ('ENT_SAM_JOSEPH','Joseph (Samaritan ancestor of the Josephite tribes)','Patriarch','Patriarch','Samaritan','Tribal ancestor of Ephraim and Manasseh','C','Samaritans identify principally as descendants of Joseph through Ephraim and Manasseh (the ''B''nei Yosef''); Joseph and Gerizim/Shechem are central to their self-understanding. Reception of the Pentateuchal Joseph (ENT_ISR_JOSEPH).'),
 ('ENT_SAM_JOSHUA','Joshua (Samaritan: builder of the Gerizim altar)','Hero / Leader','Hero / Leader','Samaritan','Conqueror who established worship at Gerizim/Shechem','C','In Samaritan tradition (incl. the Samaritan Book of Joshua/Chronicle) Joshua leads Israel into the land and establishes the sanctuary at Gerizim near Shechem, inaugurating the period of Divine Favor (Rahuta). Reception of the Israelite Joshua (ENT_ISR_JOSHUA).'),
 ('ENT_SAM_RAHUTA_FANUTA','Rahuta and Fanuta (Favor and Disfavor)','Cosmological concept','Cosmological concept','Samaritan','Periodized divine Favor/Turning-away of history','C','Samaritan periodization of sacred history into Rahuta (the era of divine Favor, from Moses/Joshua) and Fanuta (the era of divine Disfavor/turning-away, beginning with Eli''s schism), to be ended by the Taheb. Attested in Samaritan chronicles and Pummer.');
