INSERT INTO _p VALUES
 ('ENT_SAM_PANTHEON','PER_SAMARITAN','Organizing hub for the Samaritan tradition (deity, prophets, priests, eschatology, sacred realm). Modeling device, not an attested ''pantheon'' — Samaritanism is strictly monotheistic.'),
